{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Linezolid, a close oxazolidinone analogue sharing the same core and aryl substituent pattern, is 100% bioavailable in humans after oral administration, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Linezolid absolute oral bioavailability was 0.884 in elderly hospitalized patients, confirming near-complete absorption in a clinically relevant population.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "A transferable molecule with a different scaffold showed 57% absolute oral bioavailability in the fasted state, supporting F ≥ 20% under the query condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Suvorexant showed 82% absolute oral bioavailability under fasted conditions, providing direct fasted-state evidence for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Zalcitabine absolute oral bioavailability was 80% (range 54–127%) in fasting patients, supporting high oral absorption across a range of conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Elinzanetant showed dose-independent oral bioavailability of 36.7%, above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Asciminib has an absolute bioavailability of approximately 73%, further supporting high F for a structurally transferable molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Cladribine oral bioavailability was 36% (25–68%) after overnight fasting, supporting F ≥ 20% in fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Lurasidone has low oral bioavailability of 9–19%, attributed to high first-pass metabolism; this is contradictory but outweighed by the close linezolid analogue and multiple high-F transferable molecules.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analogue of linezolid, which has near-complete oral bioavailability in humans. Multiple transferable molecules with diverse scaffolds also show F values well above 20%, including under fasted conditions. The only low-F evidence, lurasidone, reflects a different first-pass liability not shared by the oxazolidinone core. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule; prediction relies on the close linezolid analogue and other transferable molecules.",
    "Fasted-state-specific absolute bioavailability for linezolid is not explicitly reported, though its near-complete F is not food-dependent.",
    "The contradictory lurasidone evidence indicates that high transfer scores do not guarantee identical outcomes, but its low F is mechanistically tied to a scaffold and metabolic profile distinct from the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

